fn floorVertex(position: vec3<f32>, normal: vec3<f32>, uv: vec2<f32>, instance: u32) -> VertexOut {
    let spot = position + vec3<f32>(0.0, -1.5, 0.0);
    var o: VertexOut;
    o.clipPos = camera.viewProj * vec4<f32>(spot, 1.0);
    o.worldPos = spot;
    o.worldNormal = normal;
    o.uv = uv;
    o.ecsColor = vec3<f32>(ecs[instance * EA_ECS_STRIDE], 0.0, 0.0);
    return o;
}

fn floorFragment(input: VertexOut) -> vec4<f32> {
    let grid = abs(fract(input.uv * 20.0) - vec2<f32>(0.5));
    let edge = step(0.46, max(grid.x, grid.y));
    return vec4<f32>(vec3<f32>(0.08, 0.09, 0.11) + vec3<f32>(0.25) * edge + input.ecsColor, 1.0);
}

fn orbVertex(position: vec3<f32>, normal: vec3<f32>, uv: vec2<f32>, instance: u32) -> VertexOut {
    let base = instance * EA_ECS_STRIDE;
    let center = vec3<f32>(ecs[base + 1u], ecs[base + 2u], ecs[base + 3u]);
    let spot = center + position * ecs[base + 8u];
    var o: VertexOut;
    o.clipPos = camera.viewProj * vec4<f32>(spot, 1.0);
    o.worldPos = spot;
    o.worldNormal = normal;
    o.uv = uv;
    o.ecsColor = vec3<f32>(ecs[base + 11u], ecs[base + 12u], ecs[base + 13u]);
    return o;
}

fn orbFragment(input: VertexOut) -> vec4<f32> {
    let sun = normalize(vec3<f32>(0.3, 1.0, 0.2));
    let shade = 0.25 + 0.75 * max(dot(normalize(input.worldNormal), sun), 0.0);
    return vec4<f32>(input.ecsColor * shade, 1.0);
}

fn pennantVertex(corner: u32, instance: u32) -> VertexOut {
    let slot = f32(instance) * 0.25 - 0.875;
    let cx = select(select(0.0, 0.08, corner == 1u), 0.04, corner == 2u);
    let cy = select(0.0, 0.1, corner == 2u);
    var o: VertexOut;
    o.clipPos = vec4<f32>(slot + cx, 0.8 + cy, 0.5, 1.0);
    o.worldPos = vec3<f32>(0.0);
    o.worldNormal = vec3<f32>(0.0, 0.0, 1.0);
    o.uv = vec2<f32>(cx * 12.5, cy * 10.0);
    o.ecsColor = vec3<f32>(0.3 + 0.08 * f32(instance), 0.5, 0.9) + vec3<f32>(ecs[instance * EA_ECS_STRIDE]);
    return o;
}

fn pennantFragment(input: VertexOut) -> vec4<f32> {
    return vec4<f32>(input.ecsColor * (0.6 + 0.4 * input.uv.y), 1.0);
}

fn placeCells(index: u32) {
    let base = index * B_cells_STRIDE;
    let col = f32(index % 8u);
    let row = f32(index / 8u);
    let half = f32(7u) * 0.5;
    b_cells[base + 0u] = 0.0;
    b_cells[base + 1u] = (col - half) * 2;
    b_cells[base + 2u] = 0.0;
    b_cells[base + 3u] = (row - half) * 2;
    b_cells[base + 4u] = 0.0;
    b_cells[base + 5u] = 0.0;
    b_cells[base + 6u] = 0.0;
    b_cells[base + 7u] = 1.0;
    b_cells[base + 8u] = 1;
    b_cells[base + 9u] = 1;
    b_cells[base + 10u] = 1;
    b_cells[base + 11u] = 0.55 + 0.4 * fract(col * 0.37);
    b_cells[base + 12u] = 0.55 + 0.4 * fract(row * 0.29);
    b_cells[base + 13u] = 0.7;
}

fn sparkVertex(corner: u32, instance: u32) -> VertexOut {
    let base = instance * EA_ECS_STRIDE;
    let center = vec3<f32>(ecs[base + 0u], ecs[base + 1u], ecs[base + 2u]);
    let angle = f32(corner) * 2.0943951;
    let spot = center + vec3<f32>(cos(angle), sin(angle), 0.0) * 0.06;
    var o: VertexOut;
    o.clipPos = camera.viewProj * vec4<f32>(spot, 1.0);
    o.worldPos = spot;
    o.worldNormal = vec3<f32>(0.0, 0.0, 1.0);
    o.uv = vec2<f32>(cos(angle), sin(angle)) * 0.5 + vec2<f32>(0.5);
    o.ecsColor = vec3<f32>(1.0, 0.6 + 0.4 * ecs[base + 3u], 0.3);
    return o;
}

fn sparkFragment(input: VertexOut) -> vec4<f32> {
    return vec4<f32>(input.ecsColor, 1.0);
}

fn stirSparks(index: u32) {
    let base = index * B_sparks_STRIDE;
    let fi = f32(index);
    let turn = fi * 0.0153 + camera.simTime * 0.4;
    let reach = 2.0 + 6.0 * fract(fi * 0.618034);
    b_sparks[base + 0u] = cos(turn) * reach;
    b_sparks[base + 1u] = 0.5 + 2.0 * fract(fi * 0.137 + camera.simTime * 0.1);
    b_sparks[base + 2u] = sin(turn) * reach;
    b_sparks[base + 3u] = fract(fi * 0.271);
}
